from flask import Flask, request, jsonifyfrom flask_cors import CORSimport joblibimport tracebackimport numpy as npimport requestsimport google.generativeai as genaifrom suggestions import *app = Flask(__name__)CORS(app)# ------------------ Load ML Models ------------------ #toxic_model = joblib.load("models/toxic_model.pkl")vectorizer = joblib.load("models/tfidf_vectorizer.pkl")# Friend recommendation model and scalerrecommendation_model = joblib.load("models/recommendation_model.pkl")scaler = joblib.load("models/scaler.pkl")# ------------------ Gemini Config ------------------ #genai.configure(api_key="AIzaSyC_E7qqdjpyfCZpeNxa8kIfys5ibRk-bxw")  # ← Paste your key heredef query_gemini_model(prompt: str) -> list[str]:    """    Use Google Gemini for generating replies.    Returns a list of replies starting with '-'.    """    try:        model = genai.GenerativeModel('models/gemini-2.0-flash')  # ← Use this model        response = model.generate_content(            f"Generate exactly 3 short, friendly reply options for this message: '{prompt}'. Format each reply starting with dash '-'. Only return the 3 replies, nothing else."        )        text = response.text        replies = [line.strip() for line in text.split('\n') if line.strip().startswith('-')]        if not replies:            replies = [                "- Thanks for your message!",                "- That's interesting!",                "- I appreciate you sharing that"            ]        return replies[:3]    except Exception as e:        return [f"- Error with Gemini: {str(e)}"]# Toxicity prediction@app.route('/predict/toxicity', methods=['POST'])def predict_toxicity():    try:        data = request.get_json()        text = data.get("message", "")        if not text.strip():            return jsonify({"error": "Empty message"}), 400        X = vectorizer.transform([text])        prediction = toxic_model.predict(X)[0]        label = "toxic" if prediction == 1 else "appropriate"        return jsonify({            "prediction": label,            "raw": int(prediction)        })    except Exception as e:        print("Error:", traceback.format_exc())        return jsonify({"error": str(e)}), 500# Friend recommendation for a list of users@app.route('/predict/recommendation', methods=['POST'])def recommend_friends():    try:        data = request.get_json()  # Expecting a list of users        if not isinstance(data, list):            return jsonify({"error": "Expected a list of users"}), 400        results = []        for user in data:            friends_count = int(user.get('friendsCount', 0))            days_since_last_seen = float(user.get('days_since_last_seen', 0))            tags_count = 0  # always 0            followers_count = friends_count            friends_ratio = followers_count / (friends_count + 1)  # avoid division by zero            features = np.array([[followers_count, friends_count, tags_count, days_since_last_seen, friends_ratio]])            features_scaled = scaler.transform(features)            prediction = recommendation_model.predict(features_scaled)[0]            results.append({                "id": user.get("id"),                "recommended": bool(prediction)            })        return jsonify(results)    except Exception as e:        print("Error:", traceback.format_exc())        return jsonify({"error": str(e)}), 500# Suggest replies (text / PDF / image)@app.route("/suggest_replies", methods=["POST"])def suggest_replies():    data = request.json    message_type = data.get("messageType")    content = data.get("content")    if not message_type or not content:        return jsonify({"error": "Missing messageType or content"}), 400    try:        if message_type.upper() == "TEXT":            text_for_prompt = content        elif message_type.upper() == "PDF":            if not os.path.exists(content):                return jsonify({"error": "PDF file not found"}), 400            try:                text_for_prompt = extract_text_from_pdf(content)            except ValueError as ve:                return jsonify({"error": "PDF must contain selectable text. Image-only PDFs are not supported."}), 400        elif message_type.upper() == "IMAGE":            if not os.path.exists(content):                return jsonify({"error": "Image file not found"}), 400            text_for_prompt = extract_text_from_image(content)        else:            return jsonify({"error": "Unsupported messageType"}), 400        if not text_for_prompt.strip():            return jsonify({"error": "No text extracted from the input"}), 400    except Exception as e:        return jsonify({"error": f"Error extracting text: {str(e)}"}), 500    # Create prompt    safe_content = text_for_prompt.replace('\n', ' ')    prompt = (        f'Generate three short, natural, and human-like replies to the following message: "{safe_content}".The replies should sound authentic, friendly, and similar to how real people respond in everyday conversation.'    )    replies = query_gemini_model(prompt)    return jsonify({"replies": replies})# ------------------ Run ------------------ #if __name__ == '__main__':    app.run(port=5000, debug=True)